"install.description.stream": "استریم و نصب یک .pkg یا .fpkg را مستقیم از این کامپیوتر به PS5 شما می‌فرستد — هیچ چیز ابتدا کپی نمی‌شود و قابل اعتمادترین راه نصب است. بارگذاری و نصب ابتدا آن را روی PS5 کپی می‌کند، برای زمانی که کنسول نمی‌تواند به این کامپیوتر برسد؛ آن کپی‌ها اینجا باقی می‌مانند تا هر وقت خواستید دوباره نصب کنید.",
