"pkglib.fpkgsupport.title": "بسته‌ی جعلی (FPKG) نصب می‌کنید؟",
"pkglib.fpkgsupport.lead": "یک بسته‌ی جعلی PS5 تنها وقتی نصب می‌شود که پشتیبانی بسته‌ی جعلی از قبل روی کنسول بارگذاری شده باشد. قبل از نصب، هر سه را به این ترتیب بارگذاری کنید:",
"pkglib.fpkgsupport.kstuff": "— نسخه‌ای که پشتیبانی بسته‌ی جعلی PS5 دارد",
"pkglib.fpkgsupport.ppr": "— پچ plaintext / no-auth مربوط به PPR را اعمال می‌کند",
"pkglib.fpkgsupport.smp": "— لایه‌ی اتصال که عنوان نصب‌شده را ثبت می‌کند",
"pkglib.fpkgsupport.tail": "بدون آن‌ها کنسول نصب را رد می‌کند، یا آن را می‌پذیرد و سپس در اتصال بازی شکست می‌خورد. بسته‌های Retail و debug هیچ‌کدام از این‌ها را لازم ندارند — اگر آن را نصب می‌کنید، این یادداشت را نادیده بگیرید.",
"pkglib.installnote.title": "نصب چگونه کار می‌کند",
"pkglib.installnote.body": "ps5upload بسته را به نصب‌کننده‌ی خودش روی PS5 تحویل می‌دهد و تنها وقتی نصب را گزارش می‌کند که کنسول کل بسته را خوانده باشد؛ یک پچ نیز باید نسخه‌ی بازی را افزایش دهد. اگر نصب شکست بخورد، بسته نگه داشته می‌شود تا بتوانید دوباره تلاش کنید. FW 12+ و بسته‌های سیستمی ممکن است همچنان به Package Installer خود PS5 در Settings → System → Debug Settings → Game نیاز داشته باشند.",
"pkglib.options.heading": "گزینه‌ها",
