"pkglib.empty.body": "یک بسته‌ی نصبی .pkg یا .fpkg اضافه کنید تا روی PS5 شما بارگذاری شود، سپس از اینجا نصبش کنید. همچنین می‌توانید هر یک از آن فرمت‌ها را روی پنجره بکشید.",
