"pkglib.installAll.what": "نصب همه چیست؟",
"pkglib.installAll.whatBody": "نصب همه هر بسته‌ی آماده را به ترتیب اجرا می‌کند: بازی پایه → به‌روزرسانی‌ها → DLC. وقتی دو به‌روزرسانی از یک نسخه (یا دو بسته‌ی DLC متناقض) دارید، از چک‌باکس هر ردیف استفاده کنید تا انتخاب کنید این کنسول کدام را نصب کند — فقط یکی در هر گروه. برای خارج کردن آن گروه، تیک را بردارید. دکمه‌ی نصب روی یک ردیف همیشه فقط همان بسته را نصب می‌کند.",
