"pkg.reason.stream_unreachable": "PS5 هرگز به این کامپیوتر برای واکشی بسته نرسید. ps5upload را از فایروال این کامپیوتر عبور دهید (در ویندوز، برای هر دو شبکه Private و Public)، کامپیوتر و PS5 را با VPN خاموش روی یک شبکه نگه دارید، و Proxy Server PS5 را روی «Do Not Use» بگذارید. بارگذاری و نصب بدون این اتصال کار می‌کند.",
