"fpkg.about": "آن را به یک پوشه بازی، یا به تصویر اتصال .exfat یا .ffpkg اشاره دهید. مبدل درخت را می‌خواند، بررسی می‌کند که هر چیزی که یک بسته‌ی قابل اجرا لازم دارد موجود است، و یک .pkg قالب debug در پوشه‌ی خروجی می‌نویسد.",
"fpkg.aboutWhere": "تبدیل روی دستگاهی که موتور را میزبانی می‌کند اجرا می‌شود — این کامپیوتر، یک میزبان Docker یا دستگاه اندروید — نه روی کنسول. تا زمانی که بسته را نصب نکنید چیزی به کنسول نمی‌رسد — از این کامپیوتر استریم می‌شود یا ابتدا روی PS5 بارگذاری می‌شود.",
"fpkg.aboutSource": "منبع باید درخت بازی‌ای باشد که از قبل رمزگشایی شده است. یک نصب retail اینجا باز نمی‌شود، و بررسی زیر اگر آن را انتخاب کرده باشید این را می‌گوید.",
"fpkg.aboutFake": "نتیجه یک بسته‌ی جعلی است، بنابراین کنسول قبل از نصب نیاز به پشتیبانی بسته‌ی جعلی بارگذاری‌شده دارد: kstuff (نسخه‌ای که پشتیبانی بسته‌ی جعلی PS5 دارد)، a53_ppr_install_fast.elf و shadowmountplus.elf، به این ترتیب. Install Package همین را کنار دکمه‌ی نصب خود می‌گوید.",
"fpkg.aboutChecks": "بررسی به دنبال چه می‌گردد",
"fpkg.checkEboot": "یک eboot.bin در ریشه‌ی درخت — ماژول عنوان. باید ELF خام یا SELF پیچیده‌شده باشد؛ ماژول امضاشده‌ی retail بازبسته‌بندی نمی‌شود.",
"fpkg.checkParam": "sce_sys/param.json، و بدون sce_sys/param.sfo — یک param.sfo مسیر راه‌اندازی کنسول را به مسیر PS4 می‌فرستد.",
"fpkg.checkIcons": "یک شناسه‌ی محتوای ۳۶ نویسه‌ای، هر دو آیکون، و ماژول حقوق sce_sys/about/right.sprx.",
"fpkg.checkDrm": "اینکه مقدار DRM بسته استاندارد است. یک مقدار free یا upgradable باعث قفل شدن عنوان توسط کنسول می‌شود؛ تنها در بسته بازنویسی می‌شود، و فایل خودتان هرگز دست نمی‌خورد.",

