payloads_essentials_body: "اگر برای اولین بار کنسولی را راه‌اندازی می‌کنید، این سه مورد بیشتر آنچه ps5upload انتظار دارد پیدا کند را پوشش می‌دهند: kstuff-lite (پچ‌های کرنل که بیشتر homebrew به آن‌ها وابسته است)، ShadowMount+ (اتصال تصاویر بازی از حافظه) و nanoDNS (کنسول را خارج از مسیر به‌روزرسانی Sony نگه می‌دارد). بقیه‌ی این فهرست اختیاری است.",
payloads_curated_blurb: "{count} payload گزیده. انتشارها هنگام درخواست از GitHub واکشی و به مدت ۱ ساعت کش می‌شوند.",
payloads_add_repo: "افزودن مخزن",
payloads_add_repo_title: "پیگیری یک مخزن payload سفارشی",
payloads_add_repo_hint: "owner/name (مثلاً EchoStretch/kstuff-lite) یا URL کامل مخزن را جای‌گذاری کنید. انتشارها همانند فهرست گزیده واکشی می‌شوند؛ همان بررسی‌های ELF/zip هنگام دانلود اعمال می‌شوند. تنها مخازنی را اضافه کنید که به آن‌ها اعتماد دارید — ps5upload محتوای مخزن سفارشی را بررسی نمی‌کند.",
payloads_add_repo_placeholder: "owner/name یا https://github.com/owner/name",
payloads_add_repo_host: "میزبان",
payloads_add_repo_host_hint: "تنها هنگام وارد کردن owner/name خالی استفاده می‌شود. GitHub یا یک میزبان Gitea/Forgejo.",
payloads_add_repo_submit: "افزودن",
payloads_custom_parse_error: "owner/name (مثلاً EchoStretch/kstuff-lite) یا URL کامل مخزن را وارد کنید.",
payloads_custom_added: "{name} اضافه شد",
