payloads_custom_removed: "{name} حذف شد",
payloads_custom_badge: "سفارشی",
payloads_custom_remove: "حذف این مخزن سفارشی",
payloads_custom_remove_short: "حذف",
payloads_description: "payloadهای homebrew PS5 شخص ثالث گزیده. آخرین انتشار را بررسی، یک‌بار دانلود و سپس با یک کلیک به PS5 خود بفرستید. نسخه‌ها به‌صورت محلی کش می‌شوند تا بتوانید یک فلش autoloader USB هم بسازید.",
payloads_description_catalog: "payloadهای homebrew PS5 شخص ثالث گزیده. آخرین انتشار را بررسی، یک‌بار دانلود و سپس با یک کلیک به PS5 خود بفرستید. نسخه‌ها به‌صورت محلی کش می‌شوند تا بتوانید یک فلش autoloader USB هم بسازید.",
payloads_description_send: "هر فایل payload PS5 — .elf، .bin، .js، .lua یا .jar (kstuff، بارگذارهای homebrew سفارشی، اکسپلویت‌های مرحله‌ی مرورگر، اسکریپت‌های پلاگین، JARهای BD-JB) — را به PS5 خود بفرستید. همان جریان تب Connection، فقط به فایلی که انتخاب می‌کنید اشاره می‌کند. توجه: payloadهای .jar سبک BD-JB به یک بارگذار JAR-aware روی پورتی غیر از 9021 نیاز دارند — پورت را روی هر چیزی که بارگذار شما گوش می‌دهد تنظیم کنید.",
payloads_tab_catalog: "کاتالوگ",
payloads_tab_shadowmount: "ShadowMount+",
