payloads_description_shadowmount: "بررسی وضعیت ShadowMount+، تصاویر بازی متصل، پیکربندی و عیب‌یابی روی PS5 انتخاب‌شده.",
payloads_description_nanodns: "پیکربندی payload nanoDNS، تأیید نسخه‌ی در حال اجرا و اعمال مهاجرت‌های پیکربندی ایمن.",
