game_activity_reset_explain:
  "این به‌طور دائم زمان بازی‌ای که ps5upload روی این کنسول ثبت کرده را حذف می‌کند. قابل بازگردانی نیست و نشست‌های گذشته قابل بازیابی نیستند. سوابق خود کنسول تحت تأثیر قرار نمی‌گیرند — این فقط آنچه این صفحه نشان می‌دهد را پاک می‌کند.",
