"install.error.notPkg": "فایل‌های رهاشده .pkg / .ffpkg / .ffpfs نیستند. اینجا تنها قالب‌های بسته‌ی PS5 پشتیبانی می‌شوند.",
kernellog_default_hidden_explainer: "دسته‌های پنهان پیش‌فرض زیرسیستم‌های خود Sony هستند که به‌طور مداوم روی هر PS5 jailbreak شده بدون توجه به payload در حال اجرا منتشر می‌شوند. آن‌ها ناشی از ps5upload نیستند. دسته‌های crash، ps5upload و سایر payloadها به‌طور پیش‌فرض همیشه قابل مشاهده هستند.",
sendpayload_elfldr_convention: "مطابق قرارداد elfldr — تنها اگر بارگذار شما جای دیگری گوش می‌دهد تغییر دهید.",
sendpayload_sent_followup: "اگر فایل یک payload کارآمد بود، PS5 شما اکنون آن را اجرا می‌کند. بیشتر بارگذارها تغییر رابط آشکاری نشان نمی‌دهند — اعلان یا نشانگر وضعیت خود payload را روی کنسول بررسی کنید.",
sendpayload_no_sends_yet: "هنوز ارسالی نیست. ارسال‌های موفق و ناموفق هر دو برای پخش سریع اینجا ظاهر می‌شوند.",
