log_level_trace: "ردیابی",
logs_disk_hint: "برای گزارش‌های اشکال روی دیسک ذخیره می‌شود. سطح ثبت:",
logs_open_folder: "باز کردن پوشه‌ی گزارش‌ها",
settings_bug_report_title: "گزارش اشکال",
settings_bug_report_hint: "مشکل را توصیف کنید، اسکرین‌شات‌ها را پیوست کنید و گزارش‌ها + یک اسنپ‌شات PS5 را در یک .zip برای پست در Discord بسته‌بندی کنید.",
settings_bug_report_open: "باز کردن گزارش اشکال",
bug_report_page_title: "گزارش اشکال",
bug_report_page_desc: "توصیف کنید چه اشتباه شد، اسکرین‌شات‌ها را پیوست کنید، و گزارش‌ها + یک اسنپ‌شات PS5 را در یک .zip برای پست در Discord بسته‌بندی کنید.",
bug_report_describe_title: "چه اتفاقی افتاد؟",
bug_report_describe_ph: "مراحل بازتولید، چه انتظاری داشتید، به‌جایش چه شد. فریم‌ور، jailbreak/بارگذار، اندازه‌ی فایل‌ها — هر چیزی که کمک کند.",
bug_report_images_title: "اسکرین‌شات‌ها",
