keep_ps5_awake_mode_hint: "به‌طور دوره‌ای تایمر استندبای خودکار PS5 را بازنشانی می‌کند تا نتواند به حالت استراحت برود. «در طول انتقال‌ها» بارگذاری‌های طولانی را محافظت می‌کند (علت شایع بارگذاری‌های ناموفق؛ پیش‌فرض). «همیشه هنگام اتصال» هر کنسولی با راهنمای در حال اجرا را تا زمانی که برنامه باز است از حالت استراحت دور نگه می‌دارد. بردن دستی PS5 به حالت استراحت در هر حالت همچنان کار می‌کند.",
