upload_system_file_read: "اجازه‌ی دانلود فایل‌های سیستمی (/system، /system_data)",
upload_system_file_read_hint: "به مرورگر FileSystem اجازه می‌دهد فایل‌ها را از پارتیشن‌های سیستمی فقط‌خواندنی که معمولاً مسدود هستند دانلود کند (مثلاً /system/common/lib، /system_data/priv). فقط‌خواندنی — هرگز روی حذف، جابجایی یا نوشتن اثر نمی‌گذارد. پیش‌فرض خاموش؛ تنها اگر می‌دانید چه می‌کنید روشن کنید.",
