upload_split_pick_entry_title: "به‌جایش \"{name}\" را انتخاب کنید",
upload_split_pick_entry_body: "این یک جلد از یک مجموعه‌ی تقسیم‌شده است، نه کل آرشیو. فایل بالا را انتخاب کنید و جلدهای باقی‌مانده به‌طور خودکار خوانده می‌شوند — نیازی نیست آن‌ها را جداگانه بارگذاری کنید.",
upload_split_unsupported_title: "این یک آرشیو تقسیم‌شده ({count} جلد) است که ps5upload نمی‌تواند باز کند",
upload_split_unsupported_body: "بارگذاری آن جلد خام را به PS5 شما می‌فرستد که نمی‌تواند از آن استفاده کند. ابتدا جلدها را به یک آرشیو واحد بازگردانید — جلد اول را با 7-Zip یا WinRAR باز و استخراج کنید، سپس پوشه‌ی استخراج‌شده یا یک آرشیو واحد از آن را بارگذاری کنید.",
upload_split_unsupported_target: "در این ادغام می‌شود: {name}",
