library_mount_modal_rw_title: "خواندن-نوشتن — می‌توانید این تصویر را ویرایش کنید",
library_mount_modal_rw_body: "با این روش می‌توانید فایل‌ها را جایگزین کنید، DLC اضافه کنید یا یک پچ backport اعمال کنید — از مرورگر فایل برای ویرایش اتصال استفاده کنید. تغییرات مستقیم در فایل تصویر نوشته می‌شوند: یک ویرایش بد می‌تواند بازی را غیرقابل بوت کند و بازگردانی وجود ندارد، پس اگر مهم است ابتدا از تصویر کپی بگیرید. PS5 ممکن است خودش هم داده‌ی ذخیره در تصویر متصل بنویسد.",
