fs_add_files_dialog_title: "فایل‌های برای کپی روی PS5 انتخاب کنید",
fs_replace: "جایگزینی فایل",
fs_replace_tooltip: "بازنویسی این فایل با یکی از کامپیوتر شما — روش پچ یک فایل داخل یک تصویر بازی متصل",
fs_replace_dialog_title: "فایل جایگزین برای \"{name}\" را انتخاب کنید",
fs_replace_confirm_title: "این فایل جایگزین شود؟",
fs_replace_confirm_body: "\"{name}\" بازنویسی می‌شود و محتوای قدیمی برای همیشه از بین می‌رود. اگر این داخل یک تصویر بازی متصل است، یک فایل بد می‌تواند بوت بازی را متوقف کند.",
