"joberr.ava1_commit_exists": "فایل بارگذاری شد اما چون مقصد از قبل وجود دارد، قابل انتشار نبود. برای جایگزینی «Override» را انتخاب کنید، یا مقصد دیگری برگزینید.",
"joberr.ava1_cross_device": "مقصد روی درایوی غیر از محل مرحله‌بندی قرار دارد، بنابراین PS5 نتوانست فایل را به جای خود منتقل کند. مقصدی روی همان درایو برگزینید، یا ابتدا روی درایو داخلی بارگذاری کنید.",
"joberr.ava1_wrong_console": "دستگاه در این نشانی همان PS5ای نیست که این برنامه با آن جفت شده است. نشانی را بررسی کنید، یا دوباره با این کنسول جفت شوید.",
"joberr.ava1_no_identity": "این برنامه هنوز هویت جفت‌سازی ندارد. از صفحه‌ی اتصال آن را با PS5 جفت کنید، سپس دوباره تلاش کنید.",
"joberr.zip_read_error": "خواندن فایل .zip ممکن نشد (ممکن است فایل یا درایو آن در میانه‌ی خواندن از دسترس خارج شده باشد). بررسی کنید منبع هنوز وصل است، سپس روی «تلاش دوباره» بزنید.",
"joberr.ava1_zip_corrupt": "خواندن این فایل .zip ممکن نشد: آسیب‌دیده یا ناقص است. دوباره دانلودش کنید یا از نو بسازید، سپس دوباره تلاش کنید.",
"joberr.ava1_7z_corrupt": "خواندن این فایل .7z ممکن نشد: آسیب‌دیده یا ناقص است. دوباره دانلودش کنید یا از نو بسازید، سپس دوباره تلاش کنید.",
"joberr.ava1_7z_encrypted": "این فایل .7z رمزگذاری شده است و بارگذار نمی‌تواند آن را استریم کند. آن را روی کامپیوتر خود استخراج کنید و به‌جایش پوشه را بارگذاری کنید.",
"joberr.ava1_7z_unsafe_path": "این فایل .7z مسیر فایل ناایمنی دارد (از پوشه‌ی خودش بیرون می‌رود). آن را روی کامپیوتر خود استخراج کنید و به‌جایش پوشه را بارگذاری کنید.",
"joberr.rar_password": "این فایل .rar به رمز عبور نیاز دارد، یا رمز واردشده اشتباه بود. رمز درست را وارد کنید و دوباره تلاش کنید.",
"joberr.rar_corrupt": "این فایل .rar آسیب‌دیده است، یا برخی بخش‌هایش وجود ندارند یا ترتیبشان درست نیست. مطمئن شوید همه‌ی بخش‌ها موجودند، سپس دوباره تلاش کنید.",
"joberr.ava1_copy_lost": "PS5 ردّ این کپی را از دست داد (هلپر دوباره راه‌اندازی شد یا اتصال قطع شد). برای شروع دوباره روی «تلاش دوباره» بزنید.",
"joberr.ava1_copy_failed": "PS5 نتوانست کپی را تمام کند. فضای خالی و در دسترس بودن مبدأ و مقصد را بررسی کنید، سپس دوباره تلاش کنید.",
"joberr.ava1_local_io": "این کامپیوتر نتوانست فایل دانلودشده را بنویسد. مجوزها و فضای خالی پوشه‌ی مقصد را بررسی کنید، سپس دوباره تلاش کنید.",
"joberr.ava1_bad_manifest": "PS5 فهرست فایلی فرستاد که این برنامه نتوانست آن را بفهمد. هلپر و این برنامه را به یک نسخه به‌روزرسانی کنید، سپس دوباره تلاش کنید.",
"joberr.helper_not_ava1": "هلپر PS5 در حال اجرا نیست. آن را از صفحه‌ی اتصال بفرستید (یا اگر بنر پیشنهاد داد از «به‌روزرسانی هلپر» استفاده کنید)، سپس دوباره تلاش کنید.",
"joberr.helper_not_ava1_web": "هلپر PS5 در حال اجرا نیست. این رابط وب نمی‌تواند آن را بفرستد: payload برنامه‌ی ps5upload را با بارگذار payload همیشگی‌تان روی کنسول اجرا کنید (یا اگر بنر پیشنهاد داد از «به‌روزرسانی هلپر» استفاده کنید)، سپس دوباره تلاش کنید.",
"joberr.helper_old": "PS5 هلپر قدیمی‌تری اجرا می‌کند. در بنر بالای صفحه روی «به‌روزرسانی هلپر» بزنید، سپس دوباره تلاش کنید.",
"joberr.not_paired": "این PS5 هنوز این برنامه را نپذیرفته است. آن‌ها را جفت کنید (دکمه‌ی «جفت‌سازی…»)، سپس دوباره تلاش کنید.",
"joberr.helper_starting": "هلپر PS5 هنوز در حال راه‌اندازی است. چند ثانیه صبر کنید، سپس دوباره تلاش کنید.",
"joberr.ava1_failed": "هلپر PS5 راه‌اندازی شد اما سرور انتقال آن بالا نیامد. کنسول را راه‌اندازی مجدد کنید، سپس دوباره تلاش کنید.",
"joberr.helper_not_running": "هیچ هلپری روی PS5 در حال اجرا نیست. ابتدا هلپر را بفرستید (صفحه‌ی اتصال در برنامه‌ی دسکتاپ، یا بارگذار payload شما)، سپس دوباره تلاش کنید.",
"install_hint_setup_exe": "نصب‌کننده باز شد: از آن پیروی کنید تا PS5Upload را در جا به‌روزرسانی کند.",
