"fakegame.fw.body": "نصب می‌شود، اما بسته‌های بازی جعلی PS5 روی فریم‌ور بالاتر از {last} قابل اجرا نیستند. بسته‌های PS4 مشکلی ندارند و برنامه‌های homebrew برای PS5 به‌طور عادی اجرا می‌شوند.",
"fakegame.fw.launch": "بسته‌های بازی جعلی PS5 روی فریم‌ور بالاتر از {last} قابل اجرا نیستند (این کنسول روی {fw} است). اگر این بازی از یک بسته‌ی جعلی نصب شده، به همین دلیل اجرا نمی‌شود. بسته‌های PS4 مشکلی ندارند.",
"fakegame.fw.more": "چرا؟",
